import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第三十四卦 大壮 雷天大壮 震上乾下","description":"周易 - 第三十四卦 大壮 雷天大壮 震上乾下","frontmatter":{"title":"第三十四卦 大壮 雷天大壮 震上乾下","description":"周易 - 第三十四卦 大壮 雷天大壮 震上乾下"},"headers":[],"relativePath":"zh/classics/zhouyi/035.md","filePath":"zh/classics/zhouyi/035.md"}'),l={name:"zh/classics/zhouyi/035.md"};function t(s,a,n,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="大壮" tabindex="-1">大壮 <a class="header-anchor" href="#大壮" aria-label="Permalink to “大壮”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>利贞。 彖曰：大壮，大者壮也。刚以动，故壮。大壮利贞；大者正也。正大而天地之情可见矣！</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>雷在天上，大壮；君子以非礼勿履。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>壮于趾，征凶，有孚。象曰：壮于 趾，其孚穷也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>贞吉。象曰：九二贞吉，以中也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>小人用壮，君子用罔，贞厉。羝羊触藩，羸其角。象曰：小人用壮，君子罔也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>贞吉悔亡，藩决不羸，壮于大舆之輹。象曰：藩决不羸，尚往也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>丧羊于易，无悔。象曰：丧羊于易，位不当也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>羝羊触藩，不能退，不能遂，无攸利，艰则吉。象曰：不能退，不能遂，不祥也。艰则吉，咎不长也。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
